insert into public.football_team_profiles (team_id, nickname, tags, intro) values
(68, '카나리스', '{노리치,캐로 로드,1902년 창단}', $t$<p>노리치 시티는 잉글랜드 동부 노퍽주의 중심 도시 노리치를 연고로 하는 구단입니다. 이 지역에서 오래전부터 카나리아를 길렀던 전통 때문에 "카나리스"라는 별명과 노란색·초록색 유니폼이 생겼습니다. 1962년과 1985년 리그컵 우승을 차지했고, 프리미어리그 첫 시즌인 1992-93 시즌에는 3위에 올랐으며 이어진 UEFA컵에서 바이에른 뮌헨을 꺾기도 했습니다. 이웃 입스위치 타운과 치르는 이스트앵글리아 더비는 지역 최대의 라이벌전입니다.</p><p>토리코리 관전 포인트: 노리치는 공을 오래 소유하며 경기를 풀어 가려는 성향이 강한 팀으로 알려져 있습니다. 홈 경기당 승점과 원정 경기당 승점의 차이가 큰 시즌이 많으니, 경기 장소를 먼저 확인하고 두 지표를 비교해 보세요.</p>$t$),
(342, '램스', '{더비,프라이드 파크 스타디움,1884년 창단}', $t$<p>더비 카운티는 잉글랜드 중부 이스트미들랜즈의 도시 더비를 연고로 하며, 1888년 풋볼리그 창립 회원 12개 구단 가운데 하나입니다. 브라이언 클러프 감독 시절인 1971-72 시즌과 데이브 매케이 감독 시절인 1974-75 시즌에 1부 리그 정상에 올랐고, 1946년에는 FA컵을 들어 올렸습니다. "램스(숫양)"라는 별명은 지역 연대의 마스코트에서 비롯됐습니다. 노팅엄 포리스트와 치르는 이스트미들랜즈 더비는 클러프가 두 팀을 모두 이끌었다는 인연 때문에 더욱 유명합니다.</p><p>토리코리 관전 포인트: 프라이드 파크는 관중 열기가 뜨거워 더비의 홈 성적이 원정보다 눈에 띄게 좋은 경우가 많습니다. 홈 경기당 승점과 무실점 비율을 함께 보면 홈에서 얼마나 단단한 팀인지 파악할 수 있습니다.</p>$t$),
(404, '레드 드래건스', '{렉섬,레이스코스 그라운드,1864년 창단}', $t$<p>렉섬은 웨일스 북동부의 도시 렉섬을 연고로 하는 웨일스에서 가장 오래된 구단입니다. 홈구장 레이스코스 그라운드는 지금도 쓰이는 경기장 가운데 국가대표 경기를 가장 먼저 치른 곳으로 꼽힙니다. 2021년 할리우드 배우 라이언 레이놀즈와 롭 매컬헤니가 구단을 인수한 뒤 다큐멘터리로 세계적인 관심을 받았고, 2023년부터 2025년까지 세 시즌 연속 승격이라는 기록을 세웠습니다. 1992년 FA컵에서 당시 1부 리그 챔피언 아스널을 꺾은 경기도 구단 역사의 명장면으로 남아 있습니다.</p><p>토리코리 관전 포인트: 연속 승격을 거친 팀은 한 단계 높은 리그에서 수비가 흔들리는 시기를 겪기 쉽습니다. 렉섬 경기를 볼 때는 경기당 실점과 후반 실점 비율을 살펴 체력이 떨어지는 시간대에 버티는 힘이 있는지 확인해 보세요.</p>$t$),
(1126, '임프스', '{링컨,신실 뱅크,1883년 창단}', $t$<p>링컨 시티는 잉글랜드 동부 링컨셔주의 역사 도시 링컨을 연고로 하는 구단입니다. "임프스"라는 별명은 링컨 대성당에 새겨진 작은 요정 조각, 이른바 "링컨 임프" 전설에서 따왔습니다. 1987년 풋볼리그에서 자동 강등된 첫 구단이 되는 아픔을 겪었지만 한 시즌 만에 복귀했습니다. 2016-17 시즌에는 5부 리그 소속으로 FA컵 8강에 올라 100년 넘게 나오지 않았던 기록을 세우며 큰 화제를 모았습니다.</p><p>토리코리 관전 포인트: 링컨은 끈질긴 수비와 세트피스로 승점을 쌓는 경기가 많은 팀입니다. 2.5골 오버 비율이 낮고 무실점 비율이 높게 나오는지 확인하면 저득점 경기가 얼마나 자주 나오는지 가늠할 수 있습니다.</p>$t$),
(343, '보로', '{미들즈브러,리버사이드 스타디움,1876년 창단}', $t$<p>미들즈브러는 잉글랜드 북동부 티스강 하구의 공업 도시 미들즈브러를 연고로 하는 구단입니다. 2004년 리그컵에서 우승하며 창단 128년 만에 첫 주요 대회 트로피를 차지했고, 2006년에는 UEFA컵 결승까지 올랐습니다. 1995년 오랫동안 쓰던 에이어섬 파크를 떠나 강변에 지은 리버사이드 스타디움으로 옮겼습니다. 선덜랜드, 뉴캐슬과 함께 북동부 라이벌 구도를 이루고 있습니다.</p><p>토리코리 관전 포인트: 미들즈브러 경기는 전반과 후반의 흐름이 다르게 나타나는 경우가 많습니다. 팀 분석의 전반·후반 득실점을 보면 경기 초반에 몰아치는 팀인지, 후반에 힘을 내는 팀인지 쉽게 구분할 수 있습니다.</p>$t$),
(384, '라이언스', '{런던,더 덴,1885년 창단}', $t$<p>밀월은 런던 동부 아일오브독스의 통조림 공장 노동자들이 만든 구단으로, 지금은 템스강 남쪽 버먼지의 더 덴을 홈으로 씁니다. 2004년 2부 리그 소속으로 FA컵 결승에 올라 맨체스터 유나이티드와 맞붙었고, 이 덕분에 구단 역사상 처음으로 유럽 대항전에 나섰습니다. "아무도 우리를 좋아하지 않아도 상관없다"는 응원가로 상징되는 거칠고 끈끈한 팬 문화가 유명합니다. 웨스트햄과의 라이벌 관계는 런던에서 가장 험악한 것으로 꼽힙니다.</p><p>토리코리 관전 포인트: 밀월은 몸싸움과 롱볼을 앞세워 상대를 불편하게 만드는 팀으로 알려져 있어, 홈인 더 덴에서는 강팀도 고전하곤 합니다. 홈 무실점 비율과 양팀 득점 비율을 함께 보면 밀월 홈경기가 얼마나 빡빡하게 흘러가는지 알 수 있습니다.</p>$t$),
(332, '블루스', '{버밍엄,세인트 앤드루스,1875년 창단}', $t$<p>버밍엄 시티는 잉글랜드 제2의 도시 버밍엄을 연고로 하며, 스몰 히스 얼라이언스라는 이름으로 출발했습니다. 1963년과 2011년 두 차례 리그컵 우승을 차지했고, 특히 2011년 결승에서는 아스널을 꺾어 큰 이변을 일으켰습니다. 2024-25 시즌에는 3부 리그에서 승점 111점이라는 기록적인 성적으로 우승하며 한 시즌 만에 챔피언십으로 돌아왔습니다. 애스턴 빌라와 치르는 세컨드 시티 더비는 도시를 둘로 나누는 라이벌전입니다.</p><p>토리코리 관전 포인트: 하위 리그에서 이기는 데 익숙해진 팀은 한 단계 높은 리그에서 무승부가 늘어나는 경우가 많습니다. 버밍엄의 최근 5경기 결과와 경기당 승점을 함께 보면 상위 리그 적응 속도를 판단하는 데 도움이 됩니다.</p>$t$),
(328, '클래러츠', '{번리,터프 무어,1882년 창단}', $t$<p>번리는 잉글랜드 북서부 랭커셔주의 작은 공업 도시 번리를 연고로 하며, 1888년 풋볼리그 창립 회원 가운데 하나입니다. 1920-21 시즌과 1959-60 시즌 1부 리그 우승, 1914년 FA컵 우승을 차지한 전통 있는 구단입니다. 홈구장 터프 무어는 1883년부터 쓰고 있어 같은 곳에서 가장 오래 경기를 치른 구장 가운데 하나입니다. "클래러츠"라는 별명은 와인색 유니폼에서 나왔고, 블랙번 로버스와의 이스트랭커셔 더비가 대표 라이벌전입니다.</p><p>토리코리 관전 포인트: 번리는 승격과 강등을 자주 오가며 2부 리그에서 강한 수비로 승점을 쌓아 온 팀입니다. 무실점 비율과 경기당 실점을 먼저 보고, 득점이 적은 경기를 얼마나 승리로 바꾸는지 확인해 보세요.</p>$t$),
(60, '트로터스', '{볼턴,터프시트 커뮤니티 스타디움,1874년 창단}', $t$<p>볼턴 원더러스는 잉글랜드 북서부 그레이터맨체스터의 도시 볼턴을 연고로 하며, 1888년 풋볼리그 창립 회원 가운데 하나입니다. FA컵을 네 차례 들어 올렸는데, 그중 1923년 결승은 웸블리 스타디움에서 열린 첫 FA컵 결승으로 유명합니다. 2000년대에는 프리미어리그에서 꾸준히 경쟁했고 UEFA컵 무대도 밟았습니다. 2009년부터 2015년까지 이청용이 뛰며 한국 팬들에게도 친숙한 구단이 됐습니다.</p><p>토리코리 관전 포인트: 볼턴 경기를 볼 때는 홈과 원정의 경기당 승점을 나눠 보는 것이 좋습니다. 원정 성적이 홈과 비슷하게 유지되는 시기가 팀이 안정적으로 돌아가는 시기라고 보면 됩니다.</p>$t$),
(387, '로빈스', '{브리스틀,애슈턴 게이트,1894년 창단}', $t$<p>브리스틀 시티는 잉글랜드 남서부의 항구 도시 브리스틀을 연고로 하며, 붉은 유니폼 때문에 "로빈스(울새)"라는 별명을 얻었습니다. 1906-07 시즌 1부 리그 준우승을 차지했고, 1909년에는 FA컵 결승에 올랐습니다. 홈구장 애슈턴 게이트는 럭비 구단과 함께 쓰는 경기장으로, 2010년대에 대대적인 개보수를 거쳤습니다. 같은 도시의 브리스틀 로버스와 치르는 브리스틀 더비가 대표 라이벌전입니다.</p><p>토리코리 관전 포인트: 브리스틀 시티는 중위권에서 접전을 많이 치르는 팀이라 무승부 비율이 성적을 좌우하는 경우가 많습니다. 양팀 득점 비율과 최근 5경기 결과를 함께 보면 비기는 경기를 승리로 바꾸고 있는지 확인할 수 있습니다.</p>$t$),
(59, '로버스', '{블랙번,이우드 파크,1875년 창단}', $t$<p>블랙번 로버스는 잉글랜드 북서부 랭커셔주의 도시 블랙번을 연고로 하며, 1888년 풋볼리그 창립 회원 가운데 하나입니다. 19세기에 FA컵을 여러 차례 차지하며 잉글랜드 초기 축구를 이끌었습니다. 1994-95 시즌에는 지역 출신 사업가 잭 워커의 투자와 케니 달글리시 감독, 앨런 시어러를 앞세워 프리미어리그 우승을 차지했습니다. 이웃 번리와의 이스트랭커셔 더비는 지역 최대의 라이벌전입니다.</p><p>토리코리 관전 포인트: 블랙번은 젊은 선수를 키워 쓰는 경우가 많아 시즌 중 경기력의 기복이 나타나기 쉽습니다. 최근 5경기 흐름과 경기당 승점을 나란히 놓고 보면 팀이 상승세인지 하락세인지 빠르게 읽을 수 있습니다.</p>$t$),
(340, '세인츠', '{사우샘프턴,세인트 메리스 스타디움,1885년 창단}', $t$<p>사우샘프턴은 잉글랜드 남부의 항구 도시 사우샘프턴을 연고로 하며, 세인트 메리 교회의 청년회 팀으로 출발해 "세인츠"라는 별명을 얻었습니다. 1976년 2부 리그 소속으로 FA컵 결승에서 맨체스터 유나이티드를 꺾은 것이 구단 역사상 가장 유명한 우승입니다. 매슈 르티시에, 앨런 시어러, 개러스 베일 등을 길러 낸 유소년 육성으로 이름이 높습니다. 이웃 포츠머스와 치르는 사우스코스트 더비가 대표 라이벌전입니다.</p><p>토리코리 관전 포인트: 사우샘프턴은 공을 소유하며 경기를 주도하려는 성향이 강한 편이라 득점과 실점이 함께 많아지는 시즌이 있습니다. 2.5골 오버 비율과 전반·후반 실점을 함께 보면 수비가 버티는 시간대를 파악할 수 있습니다.</p>$t$),
(356, '블레이즈', '{셰필드,브라몰 레인,1889년 창단}', $t$<p>셰필드 유나이티드는 잉글랜드 북부 요크셔의 철강 도시 셰필드를 연고로 합니다. "블레이즈(칼날)"라는 별명은 셰필드가 칼과 식기 생산으로 유명했던 데서 나왔습니다. 1897-98 시즌 1부 리그 우승을 차지했고 FA컵도 네 차례 들어 올렸습니다. 홈구장 브라몰 레인은 1855년 문을 연, 지금도 프로 경기가 열리는 가장 오래된 경기장 가운데 하나이며, 셰필드 웬즈데이와의 스틸 시티 더비가 대표 라이벌전입니다.</p><p>토리코리 관전 포인트: 셰필드 유나이티드는 측면 수비수까지 공격에 가담하는 적극적인 운영을 해 온 팀으로 알려져 있습니다. 경기당 득점과 원정 경기당 승점을 함께 보면 공격적인 운영이 원정에서도 통하는지 확인할 수 있습니다.</p>$t$),
(72, '스완스', '{스완지,스완지닷컴 스타디움,1912년 창단}', $t$<p>스완지 시티는 웨일스 남부의 해안 도시 스완지를 연고로 하며, 스완지 타운이라는 이름으로 출발했습니다. 2011년 웨일스 구단 최초로 프리미어리그에 올랐고, 2013년에는 리그컵 결승에서 브래드퍼드 시티를 꺾고 구단 첫 주요 대회 우승을 차지했습니다. 2012년부터 기성용이 활약하며 한국 팬들에게 널리 알려졌습니다. 카디프 시티와 치르는 사우스웨일스 더비는 웨일스에서 가장 뜨거운 라이벌전입니다.</p><p>토리코리 관전 포인트: 스완지는 짧은 패스로 경기를 풀어 가는 축구로 이름을 알린 팀입니다. 점유율이 높아도 결정력이 따라오지 않는 경기가 있으니, 경기당 득점과 무득점 경기 비율을 함께 확인해 보세요.</p>$t$),
(70, '포터스', '{스토크온트렌트,bet365 스타디움,1863년 창단}', $t$<p>스토크 시티는 잉글랜드 중부의 도자기 산업 도시 스토크온트렌트를 연고로 하며, 도자기 공업에서 따온 "포터스"라는 별명을 갖고 있습니다. 1972년 리그컵 우승이 구단의 첫 주요 대회 트로피이고, 2011년에는 FA컵 결승에 올랐습니다. 잉글랜드 축구의 전설 스탠리 매슈스가 데뷔하고 은퇴한 구단으로도 유명합니다. 2023년 대전 하나 시티즌에서 배준호가 이적해 오면서 한국 팬들의 관심도 커졌습니다.</p><p>토리코리 관전 포인트: 스토크 경기는 바람이 강하고 관중 열기가 뜨거운 홈에서 흐름이 크게 달라지곤 합니다. 홈 경기당 승점과 원정 경기당 승점의 차이를 확인하면 장소에 따른 경기력 차이를 쉽게 볼 수 있습니다.</p>$t$),
(346, '호네츠', '{왓퍼드,비커리지 로드,1881년 창단}', $t$<p>왓퍼드는 런던 북서쪽 하트퍼드셔주의 도시 왓퍼드를 연고로 하며, 노란색과 검은색 유니폼 때문에 "호네츠(말벌)"라는 별명을 얻었습니다. 가수 엘턴 존이 구단주를 맡던 시절 그레이엄 테일러 감독이 팀을 4부 리그에서 1부 리그로 끌어올렸고, 1982-83 시즌에는 1부 리그 준우승을 차지했습니다. 이어 1984년에는 FA컵 결승에도 올랐습니다. 홈구장 비커리지 로드는 1922년부터 쓰고 있습니다.</p><p>토리코리 관전 포인트: 왓퍼드는 감독 교체가 잦은 구단으로 알려져 있어 시즌 중에도 팀 색깔이 바뀌는 경우가 있습니다. 최근 5경기와 전반·후반 득실점을 함께 보면 지금의 왓퍼드가 어떤 방식으로 경기하는지 빠르게 파악할 수 있습니다.</p>$t$),
(76, '울브스', '{울버햄프턴,몰리뉴 스타디움,1877년 창단}', $t$<p>울버햄프턴 원더러스는 잉글랜드 중부 웨스트미들랜즈의 도시 울버햄프턴을 연고로 하며, 1888년 풋볼리그 창립 회원 가운데 하나입니다. 1950년대 스탠 컬리스 감독 시절 세 차례 1부 리그 우승을 차지했고, FA컵도 네 차례 들어 올렸습니다. 이 시기 몰리뉴에서 열린 해외 강팀과의 야간 친선경기는 유럽 클럽 대항전이 생기는 계기 가운데 하나로 꼽힙니다. 2021년 황희찬이 합류하며 한국 팬들에게 친숙해졌고, 웨스트 브로미치 앨비언과의 블랙컨트리 더비가 대표 라이벌전입니다.</p><p>토리코리 관전 포인트: 울브스는 수비를 두텁게 세운 뒤 빠른 역습으로 득점하는 경기가 많은 팀입니다. 무실점 비율과 후반 득점을 함께 보면 경기 후반 역습이 얼마나 효과를 내는지 확인할 수 있습니다.</p>$t$),
(74, '배기스', '{웨스트브로미치,더 호손스,1878년 창단}', $t$<p>웨스트 브로미치 앨비언은 잉글랜드 중부 웨스트미들랜즈의 도시 웨스트브로미치를 연고로 하며, 1888년 풋볼리그 창립 회원 가운데 하나입니다. FA컵을 다섯 차례 차지했고, 1919-20 시즌에는 1부 리그 우승, 1966년에는 리그컵 우승을 거뒀습니다. 홈구장 더 호손스는 잉글랜드 프로 구장 가운데 해발 고도가 가장 높은 곳으로 알려져 있습니다. 울버햄프턴 원더러스와의 블랙컨트리 더비가 대표 라이벌전입니다.</p><p>토리코리 관전 포인트: 웨스트브롬은 챔피언십에서 실점이 적은 단단한 팀으로 평가받는 시즌이 많았습니다. 경기당 실점과 2.5골 오버 비율을 함께 보면 저득점 경기를 얼마나 자주 만드는 팀인지 알 수 있습니다.</p>$t$),
(563, '해머스', '{런던,런던 스타디움,1895년 창단}', $t$<p>웨스트햄 유나이티드는 런던 동부를 연고로 하며, 템스 제철소 노동자들이 만든 팀에서 출발해 "해머스"라는 별명을 얻었습니다. 1966년 잉글랜드 월드컵 우승 멤버인 보비 무어, 제프 허스트, 마틴 피터스를 길러 내 "축구 아카데미"로 불렸습니다. FA컵 세 차례와 1965년 컵위너스컵 우승에 이어, 2023년에는 UEFA 콘퍼런스리그 우승을 차지했습니다. 2016년 업턴 파크를 떠나 런던 올림픽 주경기장이던 런던 스타디움으로 옮겼습니다.</p><p>토리코리 관전 포인트: 웨스트햄은 세트피스와 측면 크로스로 만드는 득점의 비중이 높은 팀으로 꼽혀 왔습니다. 양팀 득점 비율과 전반 실점을 함께 보면 경기 초반에 무너지는 경기가 얼마나 되는지 확인할 수 있습니다.</p>$t$),
(348, '애딕스', '{런던,더 밸리,1905년 창단}', $t$<p>찰턴 애슬레틱은 런던 남동부 찰턴을 연고로 하는 구단으로, 1947년 FA컵 우승이 대표 업적입니다. 1985년 재정 문제로 홈구장 더 밸리를 떠나야 했지만, 팬들이 정당까지 만들어 지방 선거에 나서는 등 오랜 운동을 벌인 끝에 1992년 돌아왔습니다. 2000년대 초에는 앨런 커비실리 감독 아래 프리미어리그에서 꾸준히 버텼습니다. 2025년 3부 리그 플레이오프 결승에서 이기며 챔피언십으로 복귀했습니다.</p><p>토리코리 관전 포인트: 승격팀은 시즌 초반 원정에서 승점을 잃는 경우가 많아 원정 경기당 승점이 중요한 지표가 됩니다. 찰턴의 원정 성적과 무실점 비율을 함께 보며 2부 리그 적응 정도를 판단해 보세요.</p>$t$),
(715, '블루버즈', '{카디프,카디프 시티 스타디움,1899년 창단}', $t$<p>카디프 시티는 웨일스의 수도 카디프를 연고로 하며, 1927년 FA컵 결승에서 아스널을 꺾고 잉글랜드 밖의 구단으로는 유일하게 FA컵을 차지했습니다. 2012년 구단주가 상징색을 파란색에서 빨간색으로 바꿨다가 팬들의 반발로 2015년 다시 파란색으로 돌아온 일도 있습니다. 2013-14 시즌 처음으로 프리미어리그에 올랐고, 당시 김보경이 승격과 1부 리그 무대에 함께했습니다. 스완지 시티와 치르는 사우스웨일스 더비가 대표 라이벌전입니다.</p><p>토리코리 관전 포인트: 카디프는 강한 압박과 세트피스로 승부를 거는 경기가 많았던 팀입니다. 홈 무실점 비율과 경기당 득점을 함께 보면 적은 득점으로 승점을 지키는 경기가 얼마나 되는지 알 수 있습니다.</p>$t$),
(69, '후프스', '{런던,로프터스 로드,1882년 창단}', $t$<p>퀸스 파크 레인저스는 런던 서부 셰퍼즈 부시를 연고로 하며, 가로 줄무늬 유니폼 때문에 "후프스"라는 별명으로 불립니다. 1967년 3부 리그 소속으로 웸블리에서 열린 첫 리그컵 결승에서 웨스트 브로미치 앨비언을 꺾고 우승했고, 1975-76 시즌에는 1부 리그 준우승을 차지했습니다. 2012년에는 박지성이 입단해 주장을 맡았고 윤석영도 이 구단에서 뛰었습니다. 풀럼, 브렌트퍼드, 첼시와 함께 서런던 라이벌 구도를 이룹니다.</p><p>토리코리 관전 포인트: 로프터스 로드는 관중석이 경기장에 바짝 붙은 작은 구장이라 홈 분위기가 경기에 큰 영향을 줍니다. 홈과 원정 경기당 승점을 비교하고, 최근 5경기 흐름을 함께 보면 QPR의 기세를 판단하기 쉽습니다.</p>$t$),
(325, '폼페이', '{포츠머스,프래턴 파크,1898년 창단}', $t$<p>포츠머스는 잉글랜드 남부의 군항 도시 포츠머스를 연고로 하며, "폼페이"라는 별명으로 불립니다. 1948-49 시즌과 1949-50 시즌 1부 리그를 연속 우승했고, FA컵은 1939년과 2008년 두 차례 차지했습니다. 2010년 재정난으로 법정관리에 들어가며 4부 리그까지 추락했지만, 팬 공동 소유 시기를 거쳐 다시 일어섰습니다. 이웃 사우샘프턴과 치르는 사우스코스트 더비가 대표 라이벌전입니다.</p><p>토리코리 관전 포인트: 프래턴 파크는 오래된 구장 특유의 열기로 원정팀이 부담을 느끼는 곳입니다. 포츠머스의 홈 경기당 승점과 홈 무실점 비율을 원정 기록과 비교해 보면 홈 이점이 얼마나 큰지 확인할 수 있습니다.</p>$t$),
(1081, '릴리화이츠', '{프레스턴,딥데일,1880년 창단}', $t$<p>프레스턴 노스엔드는 잉글랜드 북서부 랭커셔주의 도시 프레스턴을 연고로 하며, 1888년 풋볼리그 창립 회원 가운데 하나입니다. 1888-89 시즌 리그와 FA컵에서 한 번도 지지 않고 우승해 "무적의 팀"이라는 이름을 얻었고, 이는 잉글랜드 최초의 더블이기도 합니다. 하얀 유니폼에서 "릴리화이츠"라는 별명이 나왔습니다. 잉글랜드의 전설적인 공격수 톰 피니가 선수 생활 내내 뛴 구단으로, 딥데일에는 그의 동상이 서 있습니다.</p><p>토리코리 관전 포인트: 프레스턴은 챔피언십에서 오래 버티며 접전을 많이 치러 온 팀입니다. 2.5골 오버 비율과 양팀 득점 비율이 낮게 나오는지 살펴보면 한 골 차 승부가 얼마나 잦은지 짐작할 수 있습니다.</p>$t$)
